/* Achievers dashboard — google.script.* for a page hosted outside Apps Script (GitHub Pages).
 * Index.html is used unchanged: it keeps calling google.script.run / google.script.history, and this
 * file sends those calls to the Supabase Edge Function instead of Apps Script.
 * window.ACHIEVERS_API_URL is set in config.js (generated by the GitHub Actions build). */
(function () {
  'use strict';
  var API = window.ACHIEVERS_API_URL;
  var TIMEOUT_MS = 120000;

  /* ---- speed: answers to read-only calls are kept in this tab's memory for a short time, and the months
   *      next to the one on screen are fetched quietly in the background. The server still checks the session and
   *      access rules on every fetch; nothing is stored on disk; everything is dropped on login/logout/password change. */
  var READ = { getView: 1, getOrders: 1, getTrend: 1 };
  var CLEARS = { authenticate: 1, logout: 1, changePassword: 1, resetPasswordToDefault: 1 };
  var TTL_MS = 120000, MAX_ENTRIES = 80, PREFETCH_PARALLEL = 2;
  var memo = new Map();            // key -> { t, value } (finished) or { t, wait: Promise } (in flight)
  var queue = [], running = 0, lastUserCall = 0;
  function stable(v) {                               // same key whatever order the page lists an object's fields in
    if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']';
    if (v && typeof v === 'object') return '{' + Object.keys(v).sort().map(function (k) { return JSON.stringify(k) + ':' + stable(v[k]); }).join(',') + '}';
    return JSON.stringify(v === undefined ? null : v);
  }
  function keyOf(name, args) { return name + '|' + stable(args); }
  // what Index.html sends as view options right after a fresh login (its viewExtras() defaults)
  function defaultExtras() {
    var f = { cycle: '', saleType: '', payMode: '' };
    return { orders: { status: 'CONSIDERED', page: 1, size: 25, q: '', key: '', dir: 'asc', filters: f }, trend: { team: { filter: 'all', q: '' }, ord: { q: '', filters: f }, mode: 'team' } };
  }
  function fresh(e) { return e && Date.now() - e.t < TTL_MS; }
  function remember(k, v) {
    memo.set(k, { t: Date.now(), value: v });
    while (memo.size > MAX_ENTRIES) memo.delete(memo.keys().next().value);
  }
  function clearMemo() { memo.clear(); queue.length = 0; local.stop(); }

  /* ---- browser-side filtering: the same Code.gs runs here on this person's own data package ---- */
  var local = (function () {
    var token = null, ready = false, ver = '', empVer = '', timer = null, lastPing = 0, loading = false, enginePromise = null;
    var PING_MS = window.ACHIEVERS_PING_MS || 120000, big = false;
    // Admin-size packages (the whole organisation): whole-organisation views are quicker from the server, which
    // caches them and prefetches neighbouring months; anything narrowed to a team is answered here.
    var BIG_BYTES = 2000000;
    function orgWide(args) { var sel = args && args[3]; if (!sel || typeof sel !== 'object') return true; for (var k in sel) if (sel[k]) return false; return true; }
    function engine() {
      if (window.AchieversLocal) return Promise.resolve(window.AchieversLocal);
      if (!enginePromise) enginePromise = new Promise(function (res, rej) {
        var sc = document.createElement('script'); sc.src = 'local-engine.js?v=' + (window.ACHIEVERS_VERSION || '');
        sc.onload = function () { window.AchieversLocal ? res(window.AchieversLocal) : rej(new Error('engine')); };
        sc.onerror = function () { enginePromise = null; rej(new Error('engine')); };
        document.head.appendChild(sc);
      });
      return enginePromise;
    }
    function fetchPackage(tok) {
      if (loading) return; loading = true;
      Promise.all([engine(), new Promise(function (res, rej) { send('__snapshot', [tok], res, rej); })]).then(function (r) {
        loading = false;
        var L = r[0], snap = r[1];
        if (tok !== token || !snap || snap.success === false) return;
        big = L.load(snap, tok) > BIG_BYTES; ver = snap.ver; empVer = snap.empVer; ready = true; if (!big) memo.clear();
      }, function () { loading = false; });
    }
    function ping() {
      if (!token) return;
      if (lastUserCall <= lastPing) return;                 // nobody used the page since the last check: let the session idle out as before
      lastPing = Date.now();
      var tok = token;
      send('__ping', [tok], function (r) {
        if (tok !== token) return;
        if (!r || r.success === false) { stop(); return; }   // session ended on the server: the next call there reports it
        if (r.ver !== ver || r.empVer !== empVer) fetchPackage(tok);   // newer data published: refresh the package quietly
      }, function () {});
    }
    function start(tok) { stop(); if (window.ACHIEVERS_BROWSER_FILTERING === false) return; token = tok; lastPing = Date.now(); fetchPackage(tok); timer = setInterval(ping, PING_MS); }
    function stop() { token = null; ready = false; ver = empVer = ''; if (timer) clearInterval(timer); timer = null; if (window.AchieversLocal) window.AchieversLocal.clear(); }
    function answer(name, args) { if (!ready || !window.AchieversLocal || (big && orgWide(args))) return { ok: false }; return window.AchieversLocal.run(name, args); }
    return { start: start, stop: stop, answer: answer, isReady: function () { return ready && !big; } };
  })();
  function ok_(v) { return v && typeof v === 'object' && v.success !== false; }   // never keep errors or expired sessions

  function call(name, args, ok, fail) {
    if (CLEARS[name]) clearMemo();
    if (name === 'bootstrap') {                        // first screen after login: prefetch the month before it
      return send(name, args, function (v) {
        try { if (ok_(v)) local.start(args[0]); } catch (e) {}
        try { if (ok_(v) && v.selection) after('getView', [args[0], v.selection.fy, v.selection.month, v.selection.sel || {}, defaultExtras()], v); } catch (e) {}
        if (ok) ok(v);
      }, fail);
    }
    if (!READ[name]) return send(name, args, ok, fail);
    lastUserCall = Date.now();
    var here = local.answer(name, args);                // answered in the browser: no round trip
    if (here.ok) { var hv = here.value; setTimeout(function () { if (ok) ok(hv); }, 0); return; }
    var k = keyOf(name, args), e = memo.get(k);
    if (fresh(e) && 'value' in e) { var v = e.value; setTimeout(function () { after(name, args, v); if (ok) ok(clone(v)); }, 0); return; }
    if (fresh(e) && e.wait) { e.wait.then(function (v) { if (ok) ok(clone(v)); }, function (er) { if (fail) fail(er); }); return; }
    var p = new Promise(function (res, rej) { send(name, args, res, rej); });
    memo.set(k, { t: Date.now(), wait: p });
    p.then(function (v) { if (ok_(v)) remember(k, v); else memo.delete(k); after(name, args, v); if (ok) ok(clone(v)); },
           function (er) { memo.delete(k); if (fail) fail(er); });
  }
  function clone(v) { return v && typeof v === 'object' ? JSON.parse(JSON.stringify(v)) : v; }   // the page may change what it gets

  /* after a dashboard view arrives, fetch the previous and next month with the same filters (idle, low priority) */
  function after(name, args, v) {
    if (name !== 'getView' || !ok_(v) || !v.periods || !v.periods.monthsByFy) return;
    if (local.isReady()) return;
    var months = v.periods.monthsByFy[args[1]] || [], i = months.indexOf(args[2]);
    if (i < 0) return;
    [months[i - 1], months[i + 1]].forEach(function (m) {
      if (!m) return;
      var a = args.slice(); a[2] = m;
      var k = keyOf('getView', a);
      if (!fresh(memo.get(k))) queue.push(a);
    });
    pump();
  }
  function pump() {
    while (running < PREFETCH_PARALLEL && queue.length) {
      var a = queue.shift(), k = keyOf('getView', a);
      if (fresh(memo.get(k))) continue;
      running++;
      (function (a, k) {
        var p = new Promise(function (res, rej) { send('getView', a, res, rej); });
        memo.set(k, { t: Date.now(), wait: p });
        p.then(function (v) { if (ok_(v)) remember(k, v); else memo.delete(k); }, function () { memo.delete(k); })
         .then(function () { running--; setTimeout(pump, Date.now() - lastUserCall < 400 ? 400 : 0); });
      })(a, k);
    }
  }

  function send(name, args, ok, fail) {
    var done = false, ctl = typeof AbortController === 'function' ? new AbortController() : null;
    var timer = setTimeout(function () { if (ctl) ctl.abort(); finish(null, new Error('The server took too long to respond. Please try again.')); }, TIMEOUT_MS);
    function finish(res, err) {
      if (done) return; done = true; clearTimeout(timer);
      try { if (err) { if (fail) fail(err); } else if (ok) ok(res); } catch (e) { setTimeout(function () { throw e; }); }
    }
    if (!API) return finish(null, new Error('The dashboard is not configured (missing API address).'));
    fetch(API, {
      method: 'POST',
      // text/plain keeps this a "simple" request: no CORS pre-flight round trip
      headers: { 'Content-Type': 'text/plain;charset=UTF-8' },
      body: JSON.stringify({ fn: name, args: args }),
      cache: 'no-store', credentials: 'omit', signal: ctl ? ctl.signal : undefined
    }).then(function (r) {
      return r.json().then(function (j) { return { ok: r.ok, j: j }; }, function () { return { ok: false, j: null }; });
    }).then(function (x) {
      if (x.ok && x.j && Object.prototype.hasOwnProperty.call(x.j, 'result')) finish(x.j.result);
      else finish(null, new Error((x.j && x.j.error) || 'Server request failed. Please try again.'));
    }, function () { finish(null, new Error('Server request failed. Check your connection and try again.')); });
  }

  // google.script.run.withSuccessHandler(f).withFailureHandler(g).anyServerFunction(args...)
  function runner(ok, fail, user) {
    var base = {
      withSuccessHandler: function (f) { return runner(f, fail, user); },
      withFailureHandler: function (f) { return runner(ok, f, user); },
      withUserObject: function (u) { return runner(ok, fail, u); }
    };
    return new Proxy(base, {
      get: function (t, name) {
        if (name in t) return t[name];
        if (typeof name !== 'string' || name === 'then') return undefined;
        return function () {
          var args = Array.prototype.slice.call(arguments).map(function (a) { return a === undefined ? null : a; });
          call(name, args,
            ok ? function (r) { ok(r, user); } : null,
            fail ? function (e) { fail(e, user); } : null);
        };
      }
    });
  }

  // google.script.history: push / replace / setChangeHandler on top of the browser history API
  function loc() {
    var q = {}, qs = {};
    new URLSearchParams(location.search).forEach(function (v, k) { q[k] = q[k] === undefined ? v : q[k]; (qs[k] = qs[k] || []).push(v); });
    return { hash: location.hash.replace(/^#/, ''), parameter: q, parameters: qs };
  }
  function url(params, hash) {
    var s = '';
    if (params && typeof params === 'object') {
      var u = new URLSearchParams();
      Object.keys(params).forEach(function (k) { [].concat(params[k]).forEach(function (v) { u.append(k, v); }); });
      s = u.toString(); s = s ? '?' + s : '';
    }
    return location.pathname + s + (hash ? '#' + hash : '');
  }
  var history_ = {
    push: function (state, params, hash) { history.pushState({ __gs: state == null ? null : state }, '', url(params, hash)); },
    replace: function (state, params, hash) { history.replaceState({ __gs: state == null ? null : state }, '', url(params, hash)); },
    setChangeHandler: function (fn) {
      window.addEventListener('popstate', function (e) { fn({ state: e.state && '__gs' in e.state ? e.state.__gs : null, location: loc() }); });
    }
  };

  window.google = window.google || {};
  window.google.script = window.google.script || {};
  window.google.script.run = runner(null, null, undefined);
  window.google.script.history = history_;
  window.google.script.url = { getLocation: function (cb) { cb(loc()); } };
  window.google.script.host = { close: function () {}, setHeight: function () {}, setWidth: function () {}, origin: location.origin, editor: { focus: function () {} } };
})();
